SELECT gen_random_uuid()::text, 'formula', '$\log_b x$', 'Definition of a Logarithm', '$\log_b x = y \iff b^y = x$', NULL, 'A logarithm is an exponent: the power the base must be raised to, to give $x$.', '[{"symbol":"$b$","meaning":"base ($b > 0$, $b \\ne 1$)"},{"symbol":"$x$","meaning":"argument ($x > 0$)"},{"symbol":"$y$","meaning":"the logarithm, an exponent"}]'::jsonb, 'Turn a log equation into exponent form first: $\log_2 x = 5$ means $x = 2^5 = 32$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics' AND s."normKey" = 'algebraic expressions' AND s."active"), 'Logarithms', true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
