SELECT gen_random_uuid()::text, 'formula', '$\frac{1}{\sqrt{a}+\sqrt{b}}$', 'Rationalizing a Binomial Denominator', '$\frac{1}{\sqrt{a}+\sqrt{b}} = \frac{\sqrt{a}-\sqrt{b}}{a-b}$', NULL, 'Multiplies by the conjugate to clear the radicals from a denominator.', '[{"symbol":"$a, b$","meaning":"positive numbers, $a \\ne b$"}]'::jsonb, 'The conjugate flips the middle sign, so the denominator becomes a difference of squares.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics' AND s."normKey" = 'algebraic expressions' AND s."active"), 'Laws of radicals', true, 'PENDING', now(), now()
