SELECT gen_random_uuid()::text, 'formula', '$\frac{px+q}{(x-a)(x-b)}$', 'Partial Fractions with Distinct Linear Factors', '$\frac{px+q}{(x-a)(x-b)} = \frac{A}{x-a} + \frac{B}{x-b},\quad A = \frac{pa+q}{a-b},\ B = \frac{pb+q}{b-a}$', NULL, 'Splits a rational expression into simpler fractions; the cover-up rule gives $A$ and $B$.', '[{"symbol":"$p, q$","meaning":"coefficients of the numerator"},{"symbol":"$a, b$","meaning":"the roots of the denominator, $a \\ne b$"},{"symbol":"$A, B$","meaning":"the partial-fraction numerators"}]'::jsonb, 'Cover up $(x-a)$ and put $x = a$ in what is left to get $A$; do the same for $B$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics' AND s."normKey" = 'algebraic expressions' AND s."active"), 'Rational expressions', true, 'PENDING', now(), now()
