SELECT gen_random_uuid()::text, 'formula', '$a_1 b_2 - a_2 b_1$', 'Condition for a Unique Solution of Two Linear Equations', '$a_1 b_2 - a_2 b_1 \ne 0$', NULL, 'The lines $a_1x + b_1y = c_1$ and $a_2x + b_2y = c_2$ meet at exactly one point when this is not zero.', '[{"symbol":"$a_1, b_1$","meaning":"coefficients of the first equation"},{"symbol":"$a_2, b_2$","meaning":"coefficients of the second equation"}]'::jsonb, 'When it is zero the lines are parallel (no solution) or the same line (infinitely many).', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics' AND s."normKey" = 'system of equations' AND s."active"), 'Determinants and Cramer''s rule', true, 'PENDING', now(), now()
