SELECT gen_random_uuid()::text, 'formula', '$T_{r+1}$', 'Exponent of x in a Binomial Term', '$(ax^p + bx^q)^n:\ T_{r+1} \text{ holds } x^{p(n-r) + qr}$', NULL, 'Finds which term holds a given power of $x$ without expanding.', '[{"symbol":"$a, b$","meaning":"coefficients"},{"symbol":"$p, q$","meaning":"powers of $x$ in the two terms"},{"symbol":"$n$","meaning":"the exponent"},{"symbol":"$r$","meaning":"$0, 1, \\ldots, n$"}]'::jsonb, 'Set $p(n-r) + qr$ equal to the power you want and solve for $r$; the term is $T_{r+1}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics' AND s."normKey" = 'binomial theorem' AND s."active"), 'Expansion', true, 'PENDING', now(), now()
