INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$n(A \cup B)$', 'Union of Two Sets', '$n(A \cup B) = n(A) + n(B) - n(A \cap B)$', NULL, 'Counts the members of either set once, removing those counted twice.', '[{"symbol":"$n(\\cdot)$","meaning":"number of members"},{"symbol":"$A, B$","meaning":"the sets"}]'::jsonb, 'Those in neither set: the total minus $n(A \cup B)$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics' AND s."normKey" = 'venn diagram' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$n(A \cup B \cup C)$', 'Union of Three Sets', '$n(A \cup B \cup C) = n(A) + n(B) + n(C) - n(A \cap B) - n(B \cap C) - n(A \cap C) + n(A \cap B \cap C)$', NULL, 'Inclusion-exclusion for three sets.', '[{"symbol":"$n(\\cdot)$","meaning":"number of members"},{"symbol":"$A, B, C$","meaning":"the sets"}]'::jsonb, 'Fill the Venn diagram from the centre out: the triple overlap first.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics' AND s."normKey" = 'venn diagram' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$N$', 'Number of Subsets of a Set', '$N = 2^n$', NULL, 'A set of $n$ elements has $2^n$ subsets, counting the empty set and the set itself.', '[{"symbol":"$n$","meaning":"number of elements"},{"symbol":"$N$","meaning":"number of subsets"}]'::jsonb, 'Proper subsets leave the set itself out: $2^n - 1$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics' AND s."normKey" = 'venn diagram' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Algebra' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
